<template><div class="land-details-panel"><section v-for="section in sections" :key="section.title" class="land-detail-section"><h4>{{section.title}}</h4><dl><div v-for="field in section.fields" :key="field.label"><dt>{{field.label}}</dt><dd>{{display(field.value)}}</dd></div></dl><div v-if="section.title==='Ownership and Succession'" class="detail-repeats"><article v-for="owner in land.owners||[]" :key="owner.ownerEmail"><b>{{owner.ownerEmail}}</b><span>{{owner.ownerRef||'No owner reference'}} · {{owner.sharePercent??'—'}}% · {{owner.isDeceased?'Deceased':'Active'}}</span></article></div><div v-if="section.title==='Transactions'" class="detail-repeats"><article v-for="tx in land.transactions||[]" :key="tx.id"><b>{{tx.transactionId}} · {{tx.transactionType||'Transaction'}}</b><span>{{display(tx.date)}} · {{display(tx.amountBdt)}} BDT · {{display(tx.status)}}</span><small>Deed: {{display(tx.deedRef)}} · Seller: {{display(tx.sellerRef)}} · Buyer: {{display(tx.buyerRef)}}</small></article><p v-if="!land.transactions?.length" class="muted">No transaction history recorded.</p></div></section></div></template>
<script setup lang="ts">import{computed}from'vue';const props=defineProps<{land:any}>();const sections=computed(()=>{const l=props.land,a=l.area||{};return[
{title:'Parcel',fields:[['District',a.district],['Upazila',a.upazila],['Mouza',a.mouza],['JL number',l.jlNo],['Record type',l.recordType],['Dag number',l.dagNo],['Khatian number',l.khatianNo],['Area (decimal)',l.areaDecimal],['Land class',l.landClass]]},
{title:'Documents',fields:[['Khatian reference',l.khatianRef],['Khatian status',l.khatianStatus],['Deed number',l.deedNo],['Deed date',l.deedDate],['Registration office',l.deedRegistrationOffice],['Mutation reference',l.mutationRef],['Mutation status',l.mutationStatus],['DCR reference',l.dcrRef],['DCR status',l.dcrStatus],['Dakhila reference',l.dakhilaRef],['Dakhila status',l.dakhilaStatus]]},
{title:'Ownership and Succession',fields:[['Ownership status',l.ownershipStatus],['Death indicator',l.deathIndicator],['Successor process',l.successorProcess],['Mutation after succession',l.mutationAfterSuccession],['Succession status',l.successionStatus]]},
{title:'Case and Mortgage',fields:[['Case exists',l.caseExists],['Case reference',l.caseRef],['Case type',l.caseType],['Case status',l.caseStatus],['Mortgage exists',l.mortgageExists],['Mortgage reference',l.mortgageRef],['Mortgage status',l.mortgageStatus]]},
{title:'Price',fields:[['Last sold price (BDT)',l.lastSoldPriceBdt],['Last sold date',l.lastSoldDate],['Last sold deed reference',l.lastSoldDeedRef],['Reserved price (BDT)',l.reservedPriceBdt],['Reserved price date',l.reservedPriceDate],['Price flag',l.priceFlag]]},
{title:'Verification',fields:[['Overall status',l.overallStatus],['Risk level',l.riskLevel],['Verification flags',l.verificationFlags],['Document-level status',l.documentLevelStatus],['Ownership check',l.ownershipCheck],['Succession check',l.successionCheck],['Case check',l.caseCheck],['Mortgage check',l.mortgageCheck],['Price check',l.priceCheck],['Verified at',l.verifiedAt],['Verification version',l.verificationVersion],['Source snapshot version',l.sourceSnapshotVersion]]},
{title:'Transactions',fields:[]},
{title:'Record metadata',fields:[['Created by',l.createdBy],['Updated by',l.updatedBy],['Created at',l.createdAt],['Updated at',l.updatedAt]]}
].map(section=>({...section,fields:section.fields.map(([label,value])=>({label,value}))}))});function display(value:any){if(value===null||value===undefined||value==='')return'—';if(typeof value==='boolean')return value?'Yes':'No';return String(value)}</script>
